using UnityEngine;
public sealed class PresentationVisual:MonoBehaviour
{
 PresentationProfile profile;int kind;SpriteRenderer original,body;Color originalColor;Transform visual;PlayerMotor motor;PlayerDash dash;Rigidbody2D rb;Vector3 ratio;bool grounded;double landed=-100,trailAt;int trails;
 public void Initialize(PresentationProfile p,int k){profile=p;kind=k;original=GetComponent<SpriteRenderer>();originalColor=original.color;motor=GetComponent<PlayerMotor>();dash=GetComponent<PlayerDash>();rb=GetComponent<Rigidbody2D>();var go=new GameObject("AV1 Visual (no collider)");go.transform.SetParent(transform,false);visual=go.transform;body=go.AddComponent<SpriteRenderer>();body.sprite=original.sprite;body.sortingLayerID=original.sortingLayerID;body.sortingOrder=original.sortingOrder;body.color=p.bodyColors[k];original.enabled=false;ratio=p.formRatios[k];ratio.z=1;visual.localScale=ratio;Mark("Eye",new Vector2(.2f,.17f),new Vector2(.15f,.12f));if(k==2)Mark("Point front",new Vector2(.43f,0),new Vector2(.28f,.28f)).localRotation=Quaternion.Euler(0,0,45);if(k==3)Mark("Barrel",new Vector2(-.43f,.12f),new Vector2(.6f,.18f));if(k==4){Mark("Crown",new Vector2(0,.36f),new Vector2(.52f,.13f));Mark("Boss mark",Vector2.zero,new Vector2(.16f,.35f));}PresentationBootstrap.Instance.Effect("form-"+k);}
 Transform Mark(string name,Vector2 at,Vector2 scale){var go=new GameObject(name);go.transform.SetParent(visual,false);go.transform.localPosition=at;go.transform.localScale=new Vector3(scale.x,scale.y,1);var sr=go.AddComponent<SpriteRenderer>();sr.sprite=original.sprite;sr.color=profile.markColor;sr.sortingLayerID=original.sortingLayerID;sr.sortingOrder=original.sortingOrder+2;return go.transform;}
 void LateUpdate(){if(profile==null)return;original.enabled=false;if(kind==2)visual.localScale=new Vector3(ratio.x*GetComponent<EnemyCharger>().Direction,ratio.y,1);if(kind==3)visual.localScale=new Vector3(ratio.x*(GetComponent<EnemyTurret>().direction<0?1:-1),ratio.y,1);if(kind==0){var hp=GetComponent<PlayerHealth>();visual.gameObject.SetActive(hp.HP>0&&RoomSession.Instance!=null&&!RoomSession.Instance.Respawning);}var c=profile.bodyColors[kind];if(original.color.r!=originalColor.r||original.color.g!=originalColor.g||original.color.b!=originalColor.b)c=original.color;body.color=new Color(c.r,c.g,c.b,original.color.a);if(kind!=0||GameState.GetOrCreate().Paused)return;float stretch=profile.jumpStretch,lean=0;if(motor.Grounded){stretch=0;if(!grounded){landed=Time.timeAsDouble;PresentationBootstrap.Instance.Effect("landing");}if(Time.timeAsDouble-landed<profile.landingSeconds)stretch=-profile.landingSquash*(1-(float)(Time.timeAsDouble-landed)/profile.landingSeconds);if(Mathf.Abs(rb.linearVelocity.x)>.2f){lean=-motor.Facing*profile.leanDegrees;PresentationBootstrap.Instance.Effect("walk");}}grounded=motor.Grounded;visual.localScale=new Vector3(ratio.x*(1-stretch)*motor.Facing,ratio.y*(1+stretch),1);visual.localRotation=Quaternion.Euler(0,0,lean);if(dash.IsDashing){if(Time.timeAsDouble>=trailAt&&trails<profile.afterimages){trailAt=Time.timeAsDouble+.16/profile.afterimages;trails++;var go=new GameObject("AV1 Afterimage");go.transform.SetPositionAndRotation(visual.position,visual.rotation);go.transform.localScale=visual.lossyScale;var sr=go.AddComponent<SpriteRenderer>();sr.sprite=body.sprite;sr.color=new Color(c.r,c.g,c.b,.35f);sr.sortingOrder=body.sortingOrder-1;go.AddComponent<PresentationFragment>().Initialize(profile.trailSeconds,Vector2.zero);PresentationBootstrap.Instance.Effect("afterimage");}}else{trails=0;trailAt=0;}}
 public static void Fragments(HitFeedback target,PresentationProfile p){var sr=target.GetComponent<SpriteRenderer>();for(int i=0;i<4;i++){var go=new GameObject("AV1 Fragment");go.transform.position=target.transform.position;go.transform.localScale=target.transform.lossyScale*.22f;var s=go.AddComponent<SpriteRenderer>();s.sprite=sr.sprite;s.color=sr.color;s.sortingOrder=sr.sortingOrder+3;go.AddComponent<PresentationFragment>().Initialize(p.fragmentSeconds,new Vector2((i%2==0?-1:1)*p.fragmentSpeed,(i<2?.6f:1.3f)*p.fragmentSpeed));}}
}
public sealed class PresentationFragment:MonoBehaviour
{
 float seconds;Vector2 velocity;double start;SpriteRenderer sprite;Color color;
 public void Initialize(float duration,Vector2 speed){seconds=duration;velocity=speed;start=Time.timeAsDouble;sprite=GetComponent<SpriteRenderer>();color=sprite.color;}
 void Update(){if(GameState.GetOrCreate().Paused)return;float t=(float)(Time.timeAsDouble-start)/seconds;if(t>=1){Destroy(gameObject);return;}transform.position+=(Vector3)(velocity*Time.deltaTime);sprite.color=new Color(color.r,color.g,color.b,color.a*(1-t));}
}
